      "Слова wy и jesteście в польском тоже есть — но они значат «вы» о нескольких людях: друзьях, детях, компании. Обратиться так к одному незнакомому человеку — заметная ошибка: звучит либо по-деревенски, либо как реплика из старого фильма. Запомни: один человек — pan/pani, группа — wy.",
