 "introAudio":"У каждого польского слова есть род — и узнать его почти всегда можно по последней букве. Сегодня разложим слова по трём коробкам: мужской, женский, средний. Научимся заменять их на on, ona, ono и посмотрим, как под род подстраивается прилагательное. И сразу приятная новость: артиклей в польском нет ни одного — ровно как в русском.",
