    "paras":[
      "Каждой коробке — своё местоимение: <b>on</b> (он), <b>ona</b> (она), <b>ono</b> (оно). И заменяют они не только людей, но и вещи — ровно как в русском: stół → <b>on</b>, kawa → <b>ona</b>, okno → <b>ono</b>. Для нас это привычно, а вот в английском или испанском курсе тут было бы отдельное мучение.",
      "Во множественном числе местоимений два: <b>oni</b> — о мужчинах и о смешанной компании, <b>one</b> — обо всех остальных. Подробно множественное число разберём в день 6, пока просто заметь, что таких форм две.",
      "И главный подарок дня: <b>артиклей в польском нет вообще</b>. Ни a/the, ни el/la — ничего. Слово живёт само по себе: dom — это и «дом», и «этот дом», и «какой-то дом»; что именно, ясно из разговора. Тем, кто начинал с английского, на этом месте становится очень легко."
    ],
    "audio":"Каждой коробке — своё местоимение: on — он, ona — она, ono — оно. И заменяют они не только людей, но и вещи, ровно как в русском: stół — on, kawa — ona, okno — ono. Во множественном числе местоимений два: oni — о мужчинах и о смешанной компании, one — обо всех остальных. Подробно множественное число разберём в день шесть. И главный подарок дня: артиклей в польском нет вообще. Ни a, ни the, ни el, ни la — ничего. Слово живёт само по себе: dom — это и «дом», и «этот дом», и «какой-то дом»; что именно, ясно из разговора.",
