      "Как только у слова есть род, под него подстраивается всё, что стоит рядом. Прилагательное меняет окончание: <b>dobry</b> chleb, <b>dobra</b> kawa, <b>dobre</b> mleko. Логика ровно русская — «хороший хлеб, хорошая книга, хорошее молоко», просто окончания другие: -y, -a, -e.",
