    "paras":[
      "Смотри и слушай: <b>trzy</b> — три, <b>cztery</b> — четыре, <b>sześć</b> — шесть, <b>siedem</b> — семь, <b>dziesięć</b> — десять. Это не совпадение и не заимствование: слова родственные, поэтому первый десяток учится быстрее, чем в любом другом языке.",
      "Внимания требуют носовые: <b>pięć</b> [пеньчь] и <b>dziewięć</b> [дзéвеньчь], <b>dziesięć</b> [дзéсеньчь] — та самая ę из курса чтения, которая перед мягкой согласной даёт лёгкий носовой призвук. И <b>sześć</b> [шэсьчь]: твёрдый шипящий sz в начале, мягкие ś и ć в конце — весь вчерашний шипящий ряд в одном слове.",
      "Ударение везде по общему правилу — на предпоследний слог: <b>cz</b>tery, <b>sie</b>dem, <b>dzie</b>sięć. Односложные (dwa, trzy, pięć) вопросов не вызывают вовсе."
    ],
    "audio":"Смотри и слушай: trzy — три, cztery — четыре, sześć — шесть, siedem — семь, dziesięć — десять. Это не совпадение и не заимствование: слова родственные, поэтому первый десяток учится быстрее, чем в любом другом языке. Внимания требуют носовые: pięć, dziewięć, dziesięć — та самая ę из курса чтения, которая перед мягкой согласной даёт лёгкий носовой призвук. И sześć: твёрдый шипящий sz в начале, мягкие ś и ć в конце — весь шипящий ряд в одном слове. Ударение везде по общему правилу, на предпоследний слог: cztery, siedem, dziesięć.",
