      "И одна честная разница. По-русски мы говорим «двадцать один год», а по-польски — <b>dwadzieścia jeden lat</b>: форма lat, а не rok. Зато 22, 23, 24 снова совпадают: dwadzieścia dwa <b>lata</b> — «двадцать два года». Так что расходится ровно одна клетка таблицы.",
