    "paras":[
      "Начнём с самого предсказуемого. Средний род во множественном числе получает <b>-a</b>: okno → okn<b>a</b>, miasto → miast<b>a</b>, jabłko → jabłk<b>a</b>, krzesło → krzesł<b>a</b>. Один шаг, никаких вариантов — и русское «окно → окна» звучит точно так же.",
      "Женский род меняет -a на <b>-y</b>: kobieta → kobiet<b>y</b>, lampa → lamp<b>y</b>, torba → torb<b>y</b>. Но после k и g вместо -y пишется <b>-i</b> — то самое правило письма, которое ты уже видел(а): książka → książk<b>i</b>, matka → matk<b>i</b>.",
      "И третий вариант: слова, которые кончаются на мягкий или шипящий согласный + a, берут <b>-e</b>: ulica → ulic<b>e</b>, restauracja → restauracj<b>e</b>. Список таких слов небольшой, и на слух они узнаются быстро.",
      "Главное правило дня: окончание берётся по образцу польского слова, а не по русскому переводу. «Книги» и książki похожи, а «улицы» и ulice — уже нет."
    ],
