      "У мужского рода те же три окончания, и выбор зависит от последнего согласного. По умолчанию <b>-y</b>: dom → dom<b>y</b>, kot → kot<b>y</b>, telefon → telefon<b>y</b>. После k и g — снова <b>-i</b>: ptak → ptak<b>i</b>. А после шипящих и мягких (cz, sz, ż, rz, c, l, j) — <b>-e</b>: klucz → klucz<b>e</b>, pokój → pokoj<b>e</b>.",
      "Иногда меняется и сам корень — ровно там, где в единственном числе стоит ó или выпадающая гласная: stół → st<b>o</b>ły, samochód → samoch<b>o</b>dy, pies → p<b>s</b>y. Русский тут подсказывает: «стол — столы», «пёс — псы», логика та же.",
      "И честная граница А1: у мужчин множественное число устроено отдельно — Polak → Polac<b>y</b>, student → studenc<b>i</b>, mężczyzna → mężczyźn<b>i</b>. Это так называемый мужской личный род, одна из самых неровных тем польской грамматики; она ждёт тебя на уровне A2. Сегодня узнавай эти формы в тексте, но не заучивай."
