   "translation":"Добрый день! Меня зовут Анна. Я из России, из Москвы. Я русская. Мне двадцать два года. Это Марек. Он поляк. Марек из Кракова. Ему двадцать один год. Пан Ковальский из Кракова. Откуда Вы? Я не из Польши, но немного говорю по-польски. Здесь дом. Этот дом большой и новый. Там два окна и три стула. Что это? Это кофе. Этот кофе хороший. Это книги. Они новые. До свидания!"
