    "title":"«У меня есть» — по-польски одним глаголом",
    "paras":[
      "Русский идёт в обход: «У меня есть кот» — подлежащее тут кот, а «иметь» вообще не звучит. Польский идёт напрямик: <b>Mam kota</b>, буквально «имею кота». Оборот «u mnie jest…» — калька, в стандартном польском так не говорят.",
      "И вот здесь появляется первый падеж. То, что имеешь, стоит в <b>bierniku</b> — это польский винительный. Женский род на -a меняет окончание на <b>-ę</b>: kawa → <b>kawę</b>, herbata → <b>herbatę</b>, książka → <b>książkę</b>, siostra → <b>siostrę</b>.",
      "Ты делаешь ровно то же самое каждый день: «книга» → «имею книгу», «сестра» → «вижу сестру». Место в предложении то же, падеж тот же — расходится только окончание: русское -у, польское -ę.",
      "🔊 Полминуты о звуке. Конечное <b>ę</b> в живой речи почти теряет носовой призвук: kawę звучит как [кáвэ], siostrę как [сьóстрэ]. Носовое [эн] из шестого урока курса чтения остаётся внутри слова (ręka), а на конце смягчается до простого [э]."
    ],
    "audio":"Русский идёт в обход: «у меня есть кот» — подлежащее тут кот, а «иметь» вообще не звучит. Польский идёт напрямик: mam kota, буквально «имею кота». Оборот «u mnie jest» — калька, в стандартном польском так не говорят. И вот здесь появляется первый падеж. То, что имеешь, стоит в bierniku — это польский винительный. Женский род на -a меняет окончание на -ę: kawa — kawę, herbata — herbatę, książka — książkę, siostra — siostrę. Ты делаешь то же самое каждый день: книга — имею книгу, сестра — вижу сестру. Расходится только окончание. И полминуты о звуке: конечное ę в живой речи почти теряет носовой призвук и звучит как простое э.",
