      "Два слова живут только во множественном: <b>rodzice</b> — родители, <b>dzieci</b> — дети (одно дитя — dziecko, оно у тебя со вчера). И ещё одно удобное: <b>rodzeństwo</b> — братья и сёстры одним словом, в русском такого нет.",
      "🔊 Полминуты о звуке: <b>córka</b> читается [цýрка]. C даёт [ц], ó звучит как [у] — оба правила ты уже знаешь из курса чтения, а вместе они дают слово, которое русский глаз прочитал бы совсем иначе."
