    "audio":"Rodzina — семья. Слово так похоже на русское «родина», что ошибка напрашивается сама, а смысл разъезжается полностью: родина по-польски — ojczyzna. Ближний круг: mama и tata — тёплые, домашние слова; matka и ojciec — нейтральные, для документов и разговора о ком-то третьем. Дальше brat, siostra, syn, córka, babcia, dziadek. Два слова живут только во множественном: rodzice — родители, dzieci — дети. И ещё одно удобное: rodzeństwo — братья и сёстры одним словом, в русском такого нет. И полминуты о звуке: córka читается как цурка. C даёт ц, а ó звучит как у.",
