    "title":"<em>Nie</em> — и что случается дальше",
    "paras":[
      "Отрицать просто: <b>nie</b> перед глаголом. Nie jestem Anna. Nie mam czasu. Одно слово, одно место — тут польский и русский совпадают полностью.",
      "Но посмотри внимательно на второй пример. Было <b>Mam czas</b>, стало <b>Nie mam czasu</b> — слово изменилось. При отрицании дополнение уходит из biernika в другой падеж: <b>dopełniacz</b>, польский родительный.",
      "Ты делаешь так всю жизнь: «есть время» → «нет времени», «есть кот» → «нет кота». Сказать «нет кот» невозможно. Механизм родной — учить придётся только окончания."
    ],
    "audio":"Отрицать просто: nie перед глаголом. Nie jestem Anna. Nie mam czasu. Одно слово, одно место — тут польский и русский совпадают полностью. Но посмотри внимательно на второй пример. Было mam czas, стало nie mam czasu — слово изменилось. При отрицании дополнение уходит из biernika в другой падеж: dopełniacz, польский родительный. Ты делаешь так всю жизнь: «есть время» — «нет времени», «есть кот» — «нет кота». Механизм родной, учить придётся только окончания.",
