      "Большинство слов берут <b>-e</b>, и перед ним последняя согласная смягчается или меняется: szkoła → w <b>szkole</b>, Warszawa → w <b>Warszawie</b>, sklep → w <b>sklepie</b>, miasto → w <b>mieście</b>, kino → w <b>kinie</b>, poczta → na <b>poczcie</b>.",
      "После k, g и у части слов идёт <b>-u</b>: park → w <b>parku</b>, bank → w <b>banku</b>, hotel → w <b>hotelu</b>. Отдельно запомни самое частое слово дня: dom → w <b>domu</b>.",
      "Чередование пугать не должно: русский делает то же самое — «рука → в руке», «доска → на доске». Полной таблицы склонения я специально не даю: на этом уровне надёжнее выучить десяток нужных мест целиком, готовыми связками, а система соберётся сама."
