      "После mam слово встаёт в biernik. Женский род на -a → <b>-ę</b> (kawa → kawę). Мужской род делится по одушевлённости: неживое не меняется (dom, telefon), живое получает <b>-a</b> (brat → brata, pies → psa). Средний род не меняется вовсе."
