    "paras":[
      "<b>Rodzina</b> — семья (родина — ojczyzna). Притяжательные mój / moja / moje согласуются с родом слова, а <b>jego, jej, ich</b> не меняются никогда — как в русском.",
      "Отрицание: <b>nie</b> перед глаголом, а дополнение уходит в dopełniacz. Женский род → -y/-i (kawa → kawy, książka → książki), средний → -a (mleko → mleka), мужской живой → -a (brat → brata), мужской неживой → чаще -u (dom → domu, czas → czasu). Отдельно: <b>nie ma</b> — «нет, отсутствует»."
    ],
    "audio":"Rodzina — семья, а родина — ojczyzna. Притяжательные mój, moja, moje согласуются с родом слова, а jego, jej, ich не меняются никогда — как в русском. Отрицание: nie перед глаголом, а дополнение уходит в dopełniacz. Женский род — -y или -i: kawa — kawy, książka — książki. Средний — -a: mleko — mleka. Мужской живой — -a: brat — brata. Мужской неживой — чаще -u: dom — domu, czas — czasu. Отдельно: nie ma — «нет, отсутствует».",
