    "eyebrow":"Повторение · День 11",
    "title":"Где? <em>w</em> и <em>na</em> + miejscownik",
    "paras":[
      "После w и na слово обязано измениться — это miejscownik, предложный падеж, который без предлога не бывает. Чаще всего окончание <b>-e</b> с чередованием (szkoła → w szkole, sklep → w sklepie, miasto → w mieście), после k и g — <b>-u</b> (park → w parku). Отдельно: dom → <b>w domu</b>.",
      "И три расхождения с русским, которые стоит держать в голове: <b>w pracy</b> («на работе»), <b>na uniwersytecie</b> («в университете»), <b>na wsi</b> («в деревне»)."
    ],
    "audio":"После w и na слово обязано измениться — это miejscownik, предложный падеж, который без предлога не бывает. Чаще всего окончание -e с чередованием: szkoła — w szkole, sklep — w sklepie, miasto — w mieście. После k и g — -u: park — w parku. Отдельно: dom — w domu. И три расхождения с русским: w pracy — «на работе», na uniwersytecie — «в университете», na wsi — «в деревне».",
