      "Это твоя родная логика: по-русски мы тоже говорим «Живу в Польше» — и всем всё ясно. В польском так же, и это норма речи, а не небрежность.",
      "Местоимение возвращают, когда нужен контраст или акцент: <b>Ja</b> czytam, a <b>ty</b> słuchasz — «Я читаю, а ты слушаешь». Здесь ja и ty несут смысл, без них противопоставление рассыплется.",
