    "paras":[
      "Теперь примерим образец к новым словам — все они на <b>-ać</b> и все спрягаются как mieszkać. <b>czytać</b> («читать»): czyt<b>am</b>, czyt<b>asz</b>. <b>oglądać</b> («смотреть»): oglądam film. <b>znać</b> («знать»): znam. <b>czekać</b> («ждать»): czekam.",
      "Два глагола стоит запомнить вместе с падежом. <b>oglądać</b> берёт biernik, как и mieć: oglądam <b>telewizję</b>, oglądam <b>film</b>. А <b>słuchać</b> требует dopełniacz — тот самый падеж, что после отрицания: słucham <b>muzyki</b>, а не «muzykę». Русское ухо тут подсказывает неверно, поэтому запомни фразу целиком.",
      "И маленький возврат к чтению: <b>mieszkam</b> [мéшкам] — sz даёт один звук [ш] (урок 4); <b>czytam</b> [чы́там] — cz это [ч], а y это [ы] (уроки 2 и 4); <b>oglądam</b> [оглóндам] — носовое ą перед d звучит как [он] (урок 6). Ударение везде на предпоследнем слоге, как ты и привык(ла)."
    ],
    "audio":"Теперь примерим образец к новым словам — все они на -ać и все спрягаются как mieszkać. czytać, читать: czytam, czytasz. oglądać, смотреть: oglądam film. znać, знать: znam. czekać, ждать: czekam. Два глагола стоит запомнить вместе с падежом. oglądać берёт biernik, как и mieć: oglądam telewizję, oglądam film. А słuchać требует dopełniacz — тот самый падеж, что после отрицания: słucham muzyki, а не «muzykę». Русское ухо тут подсказывает неверно, поэтому запомни фразу целиком. И маленький возврат к чтению: mieszkam — sz даёт один звук ш; czytam — cz это ч, а y это ы; oglądam — носовое ą перед d звучит как он. Ударение везде на предпоследнем слоге.",
