      "Есть маленькая орфографическая деталь: после шипящих <b>cz, sz, ż, rz</b> вместо -isz пишется <b>-ysz</b> — просто потому, что после этих букв в польском не пишут i. <b>tańczyć</b> («танцевать») → tańcz<b>ę</b>, tańcz<b>ysz</b>. Звучит это одинаково — разница только на бумаге.",
