      "Честно: по одной словарной форме группу не угадать. <b>czytać</b> и <b>pisać</b> оба на -ać, а спрягаются по-разному: czytam, но piszę. Поэтому польские словари дают глагол сразу с двумя формами: <i>pisać (piszę, piszesz)</i>. Эти две формы — и есть весь ключ: по ним достраиваются остальные четыре.",
      "Это не польская вредность. Русский устроен точно так же: «писать — пишу, пишешь» против «читать — читаю, читаешь». Ты просто выучил(а) это в детстве и не заметил(а). Здесь придётся заметить — зато осознанно.",
      "Практический совет: запоминай новый глагол не по словарной форме, а сразу парой «я + ты». Не «robić», а <b>robię, robisz</b>. Тогда все шесть форм собираются сами."
