    "paras":[
      "Смотри, что получается. По-русски: «мне нравится этот фильм» — тот, кому нравится, стоит в дательном («мне»), а сам фильм — подлежащее. По-польски: <b>Podoba mi się ten film</b>. Слово в слово, порядок в порядок. Такое полное совпадение — редкость, и сегодня оно на твоей стороне.",
      "Меняется только маленькое слово: <b>mi</b> (мне), <b>ci</b> (тебе), <b>mu</b> (ему), <b>jej</b> (ей), <b>nam</b> (нам), <b>wam</b> (вам), <b>im</b> (им). Это дательный падеж; полностью он придёт на A2, а сейчас бери эти семь слов готовыми.",
      "И как в русском, глагол согласуется с тем, что нравится: одно — <b>podoba</b>, много — <b>podobają</b>. Podoba mi się ta książka. Podobają mi się te książki. «Нравится» / «нравятся» — та же пара."
    ],
    "audio":"Смотри, что получается. По-русски: «мне нравится этот фильм» — тот, кому нравится, стоит в дательном, «мне», а сам фильм — подлежащее. По-польски: podoba mi się ten film. Слово в слово, порядок в порядок. Меняется только маленькое слово: mi — мне, ci — тебе, mu — ему, jej — ей, nam — нам, wam — вам, im — им. Это дательный падеж; полностью он придёт на A2, а сейчас бери эти семь слов готовыми. И как в русском, глагол согласуется с тем, что нравится: одно — podoba, много — podobają. Podoba mi się ta książka. Podobają mi się te książki.",
