    "paras":[
      "Настоящее время в польском живёт тремя семьями, и различить их проще всего по паре «я + ты». Первая: <b>-am / -asz</b> — mieszkam, czytam, słucham, znam, mam. Вторая: <b>-ę / -esz</b> — piszę, pracuję, chcę, mogę. Третья: <b>-ę / -isz</b> — robię, mówię, lubię, muszę.",
      "Местоимение при этом необязательно: окончание уже назвало лицо. <b>Mieszkam</b> w Polsce — без ja. Возвращаем его только для контраста: Ja czytam, a ty słuchasz.",
      "И два неправильных, но незаменимых: <b>iść</b> (idę, idziesz) — пешком, <b>jechać</b> (jadę, jedziesz) — на транспорте. Разница ровно как между русскими «иду» и «еду»."
    ],
    "audio":"Настоящее время в польском живёт тремя семьями, и различить их проще всего по паре «я плюс ты». Первая: -am и -asz — mieszkam, czytam, słucham, znam, mam. Вторая: -ę и -esz — piszę, pracuję, chcę, mogę. Третья: -ę и -isz — robię, mówię, lubię, muszę. Местоимение при этом необязательно: окончание уже назвало лицо. Mieszkam w Polsce, без ja. Возвращаем его только для контраста: ja czytam, a ty słuchasz. И два неправильных, но незаменимых: iść — idę, idziesz — пешком, jechać — jadę, jedziesz — на транспорте.",
