      "Второй способ спросить — <b>Jak dojść do…?</b> («как дойти до…»). После <b>do</b> — родительный падеж, вчерашний знакомый: <b>do dworca</b>, <b>do apteki</b>, <b>do parku</b>, <b>do sklepu</b>.",
      "А вот куда идут «на»: <b>na pocztę</b>, <b>na dworzec</b>, <b>na rynek</b> — и тут польский совпадает с русским («на почту», «на вокзал»). Совпадает не всегда, но именно в этих словах — да.",
      "Полезные короткие вопросы вдогонку: <b>Czy to daleko?</b> («это далеко?»), а в ответ — <b>Nie, to blisko</b> («нет, близко») или <b>Tak, to daleko</b>."
