    "eyebrow":"Правило 3 · Направления",
    "title":"Повелительное наклонение: <em>idź</em>, <em>skręć</em>",
    "paras":[
      "Ответ на вопрос о дороге почти всегда звучит в повелительном наклонении. <b>Idź prosto</b> — иди прямо. <b>Skręć w prawo</b> — поверни направо. <b>Skręć w lewo</b> — налево. <b>Przejdź przez ulicę</b> — перейди улицу.",
      "Форму делать легко: возьми форму «он/она» настоящего времени и убери окончание. on idzie → <b>idź</b>, on skręci → <b>skręć</b>, on przejdzie → <b>przejdź</b>. Голый корень — и это уже приказ, ровно как русское «иди», «сядь».",
      "У глаголов первой группы (на -a) вместо этого добавляется <b>-j</b>: ona czeka → <b>czekaj</b> (подожди), ona pyta → <b>pytaj</b> (спрашивай), ona słucha → <b>słuchaj</b> (слушай).",
      "Незнакомому человеку так не говорят. Вежливая версия проще некуда: <b>proszę</b> + инфинитив. <b>Proszę iść prosto. Proszę skręcić w prawo.</b> Ничего менять не надо — берёшь словарную форму глагола."
    ],
    "audio":"Ответ на вопрос о дороге почти всегда звучит в повелительном наклонении. Idź prosto — иди прямо. Skręć w prawo — поверни направо. Skręć w lewo — налево. Przejdź przez ulicę — перейди улицу. Форму делать легко: возьми форму «он, она» настоящего времени и убери окончание. On idzie — idź, on skręci — skręć, on przejdzie — przejdź. Голый корень — и это уже приказ, ровно как русское «иди», «сядь». У глаголов первой группы, на -a, вместо этого добавляется -j: ona czeka — czekaj, подожди, ona pyta — pytaj, спрашивай, ona słucha — słuchaj, слушай. Незнакомому человеку так не говорят. Вежливая версия проще некуда: proszę плюс инфинитив. Proszę iść prosto. Proszę skręcić w prawo. Ничего менять не надо — берёшь словарную форму глагола.",
