      "А теперь скажи по-русски: зимóй, лéтом, веснóй, óсенью. Это творительный падеж — тот самый, что был у нас под столом и над кроватью. Польский поступает точно так же: <b>zimą</b>, <b>latem</b>, <b>wiosną</b>, <b>jesienią</b>. Одна и та же идея в двух языках, разные буквы на конце.",
