      "Русское будущее собирается из двух деталей: «буду» + «читать». Польское — точно так же: <b>będę</b> + <b>czytać</b>. <b>Będę czytać.</b> — «Я буду читать». Ничего нового изобретать не нужно, только выучить формы слова «буду».",
      "Вот они целиком: <b>będę</b> (я буду), <b>będziesz</b> (ты будешь), <b>będzie</b> (он/она/оно будет), <b>będziemy</b> (мы), <b>będziecie</b> (вы), <b>będą</b> (они).",
      "Второй глагол не меняется вообще — он стоит в словарной форме: <b>Jutro będę pracować.</b> <b>W weekend będziemy odpoczywać.</b> <b>Ona będzie mieszkać w Krakowie.</b>",
      "Есть и второй, столь же правильный вариант: вместо инфинитива поляк может поставить форму на -ł — <b>będę czytał</b> (говорит мужчина) / <b>będę czytała</b> (говорит женщина). Оба варианта живые и равноправные; выбери инфинитив — он проще и подходит всегда."
