    "audio":"Русское будущее собирается из двух деталей: «буду» плюс «читать». Польское — точно так же: będę плюс czytać. Będę czytać — «я буду читать». Ничего нового изобретать не нужно, только выучить формы слова «буду». Вот они целиком: będę — я буду, będziesz — ты будешь, będzie — он, она, оно будет, będziemy — мы, będziecie — вы, będą — они. Второй глагол не меняется вообще — он стоит в словарной форме: jutro będę pracować. W weekend będziemy odpoczywać. Ona będzie mieszkać w Krakowie. Есть и второй, столь же правильный вариант: вместо инфинитива поляк может поставить форму на -ł: będę czytał, говорит мужчина, będę czytała, говорит женщина. Оба варианта живые и равноправные; выбери инфинитив — он проще и подходит всегда.",
