    "eyebrow":"Правило 1 · Был и была",
    "title":"<em>byłem</em> / <em>byłam</em>",
    "paras":[
      "Скажи по-русски: «Я был дома» — и «Я была дома». Одно и то же событие, но форма зависит от того, кто говорит. Для русского уха это само собой, а для многих языков — экзотика.",
      "Польский устроен так же. Мужчина скажет <b>byłem w domu</b>, женщина — <b>byłam w domu</b>. И это не украшение: без правильного окончания фраза звучит так же странно, как русское «я была» из уст мужчины.",
      "Формы глагола <b>być</b> в прошедшем: я — <b>byłem</b> / <b>byłam</b>; ты — <b>byłeś</b> / <b>byłaś</b>; он — <b>był</b>, она — <b>była</b>, оно — <b>było</b>.",
      "Присмотрись к букве <b>-a-</b>: именно она делает форму женской. byłem → był<b>a</b>m, byłeś → był<b>a</b>ś. Один звук — и весь род поменялся."
    ],
    "audio":"Скажи по-русски: «Я был дома» — и «Я была дома». Одно и то же событие, но форма зависит от того, кто говорит. Для русского уха это само собой, а для многих языков — экзотика. Польский устроен так же. Мужчина скажет byłem w domu, женщина — byłam w domu. И это не украшение: без правильного окончания фраза звучит так же странно, как русское «я была» из уст мужчины. Формы глагола być в прошедшем: я — byłem или byłam; ты — byłeś или byłaś; он — był, она — była, оно — było. Присмотрись к букве а: именно она делает форму женской. Byłem — byłam, byłeś — byłaś. Один звук — и весь род поменялся.",
